polyspec_orm::models!();
async fn used(db: &polyspec_orm::Db) {
    let author = || model::Author::new().connect(db);
    let _ = author;
    let _: polyspec_orm::Result<_> = author().name("a").is_close(true).gets().await;
    let _: polyspec_orm::Result<_> = author().name("a").and(()).gets().await;
    let _: polyspec_orm::Result<_> = author().seq(Vec::<i64>::new()).gets().await;
    let _: polyspec_orm::Result<_> = model::Author::new().name("a").gets().await;
    let _: polyspec_orm::Result<_> = author().for_update().gets().await;
    let _: polyspec_orm::Result<_> = author().join_user_seq_with_seq(model::User::new().connect(db)).gets().await;
    let _: polyspec_orm::Result<_> = author().limit(0, 1).gets_page(1, 10).await;
    let _: polyspec_orm::Result<_> = author().relation(model::User::new().match_user_seq_with_seq().limit(0, 1)).gets_by_seq(42).await;
    let _: polyspec_orm::Result<_> = author().name("a").or(&model::User::new()).gets().await;
}
fn main() { let _ = used; }

